def psierr(v,mode):
    old=(2*I(v)**5/25)*(-I(v)+29).exp()
    def calc(S):
        return sum(c*I(v)**(4+k)*(-I(a)*v).exp()*(1+1/(I(v)*(1-a-2/J))) for c,a,k in S+powers)+old
    if v<=58:
        return (I(v)**6+2*I(v)**5)*(-I(v)/2).exp()/25
    p=mini(calc(CH),calc(S0))
    if mode: p=mini(p,calc(S1))
    return p
