Z core(Z n,Z d){ // 1<=n/d<=2; one-sided error <210/F
 assert(d<=n&&n<=2*d&&d>0);
 Z t=(F*(n-d))/(n+d),v=t,r=0;
 Z t2=t*t/F;
 for(int j=1;j<=41;j+=2){r+=v/j; v=v*t2/F;}
 return 2*r;
}
