Z logscaled(Z n,Z d=1){ // inputs used below >=1, output lower fixed point
 assert(n>=d&&d>0);
 int k=0;
 while(n>=2*d){d*=2;++k;}
 assert(k<=30);
 return k*ln2+core(n,d);
}
